const aiResponse = $input.first().json.content.parts[0].text;
const cleanedResponse = aiResponse.replace(/```json\n?|```/g, '').trim();

let extractedData;
try {
  extractedData = JSON.parse(cleanedResponse);
} catch (e) {
  extractedData = { 
    error: "Failed to parse AI response",
    raw_response: aiResponse 
  };
}

return {
  json: {
    document_type: $('Process Documents Loop').first().json.type,
    extracted_data: extractedData,
    original_filename: $('Process Documents Loop').first().json.filename
  },
  binary: $('Download Document File').first().binary
};

// Input: Array of all extracted documents
const documents = $input.first().json.item.map(item => item);

// Initialize validation results
const validationResults = {
  is_valid: true,
  errors: [],
  warnings: [],
  documents_checked: documents.length,
  required_documents: ['tax_form', 'insurance', 'certification']
};

// 1. Check if all required document types are present
const providedTypes = documents.map(doc => doc.document_type);
const missingTypes = validationResults.required_documents.filter(
  type => !providedTypes.includes(type)
);

if (missingTypes.length > 0) {
  validationResults.is_valid = false;
  validationResults.errors.push({
    type: 'missing_documents',
    message: `Missing required documents: ${missingTypes.join(', ')}`,
    severity: 'critical'
  });
}

// 2. Validate required fields in each document
documents.forEach((doc, index) => {
  const data = doc.extracted_data;
  const requiredFields = ['company_name'];

  // Document-type specific requirements
  if (doc.document_type === 'tax_form') {
    requiredFields.push('tax_id', 'address');
  }
  if (doc.document_type === 'insurance') {
    requiredFields.push('coverage_amount', 'expiration_date');
  }
  if (doc.document_type === 'certification') {
    requiredFields.push('certificate_number', 'expiration_date', 'issuing_authority');
  }

  const missingFields = requiredFields.filter(field => !data[field] || data[field] === null);

  if (missingFields.length > 0) {
    validationResults.is_valid = false;
    validationResults.errors.push({
      type: 'missing_fields',
      document: doc.document_type,
      message: `Document ${doc.original_filename} is missing: ${missingFields.join(', ')}`,
      severity: 'high',
      fields: missingFields
    });
  }
});

// 3. Cross-document validation - Company name consistency
const companyNames = documents
  .map(doc => doc.extracted_data.company_name)
  .filter(name => name !== null);

const uniqueNames = [...new Set(companyNames.map(n => n.toLowerCase().trim()))];

if (uniqueNames.length > 1) {
  validationResults.is_valid = false;
  validationResults.errors.push({
    type: 'name_mismatch',
    message: `Company name inconsistency detected across documents: ${companyNames.join(' vs ')}`,
    severity: 'high',
    found_names: companyNames
  });
}

// 4. Check for expired certificates/insurance
const today = new Date();
documents.forEach((doc, index) => {
  const data = doc.extracted_data;

  if (data.expiration_date) {
    try {
      const expirationDate = new Date(data.expiration_date);

      if (expirationDate < today) {
        validationResults.is_valid = false;
        validationResults.errors.push({
          type: 'expired_document',
          document: doc.document_type,
          message: `${doc.document_type} has expired on ${data.expiration_date}`,
          severity: 'critical',
          expiration_date: data.expiration_date
        });
      } else if ((expirationDate - today) / (1000 * 60 * 60 * 24) < 30) {
        // Warning if expiring within 30 days
        validationResults.warnings.push({
          type: 'expiring_soon',
          document: doc.document_type,
          message: `${doc.document_type} expires soon: ${data.expiration_date}`,
          severity: 'medium'
        });
      }
    } catch (e) {
      validationResults.warnings.push({
        type: 'invalid_date_format',
        document: doc.document_type,
        message: `Could not parse expiration date: ${data.expiration_date}`
      });
    }
  }
});

// 5. Email validation
documents.forEach((doc) => {
  const email = doc.extracted_data.email;
  if (email) { 
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      validationResults.is_valid = false;
      validationResults.errors.push({
        type: 'invalid_email',
        document: doc.document_type,
        message: `Invalid email format: ${email}`,
        severity: 'medium'
      });
    }
  }
});

// 6. Tax ID format validation (if US - EIN format)
const taxDoc = documents.find(doc => doc.document_type === 'tax_form');
if (taxDoc && taxDoc.extracted_data.tax_id) {
  const taxId = taxDoc.extracted_data.tax_id.replace(/[^0-9]/g, '');
  if (taxId.length !== 9) {
    validationResults.warnings.push({
      type: 'tax_id_format',
      message: `Tax ID format may be incorrect: ${taxDoc.extracted_data.tax_id}`,
      severity: 'low'
    });
  }
}

// Return results
return {
  json: {
    validation: validationResults,
    documents: documents,
    supplier_email: $('Receive Supplier Submission (Webhook Trigger)').first().json.body.supplier_email,
    supplier_name: $('Receive Supplier Submission (Webhook Trigger)').first().json.body.supplier_name,
    submission_date: new Date().toISOString()
  }
};

const validation = $json.validation;
const supplierName = $json.supplier_name;

// Generate issue summary
let feedbackMessage = `Dear ${supplierName},\n\n`;
feedbackMessage += `Thank you for submitting your onboarding documents. Our automated review has identified some issues that need your attention:\n\n`;

// Critical errors
if (validation.errors.length > 0) {
  feedbackMessage += `**CRITICAL ISSUES:**\n`;
  validation.errors.forEach((error, index) => {
    feedbackMessage += `${index + 1}. ${error.message}\n`;

    // Add helpful guidance
    if (error.type === 'missing_documents') {
      feedbackMessage += `   → Please upload the missing document types.\n`;
    } else if (error.type === 'missing_fields') {
      feedbackMessage += `   → Please ensure all required fields are clearly visible in ${error.document}.\n`;
    } else if (error.type === 'name_mismatch') {
      feedbackMessage += `   → Ensure the company name is spelled exactly the same across all documents.\n`;
    } else if (error.type === 'expired_document') {
      feedbackMessage += `   → Please provide an updated ${error.document} with a valid expiration date.\n`;
    }
    feedbackMessage += `\n`;
  });
}

// Warnings
if (validation.warnings.length > 0) {
  feedbackMessage += `\n**WARNINGS:**\n`;
  validation.warnings.forEach((warning, index) => {
    feedbackMessage += `${index + 1}. ${warning.message}\n`;
  });
}

// Specific field-level feedback
const missingFieldsByDoc = {};
validation.errors.forEach(error => {
  if (error.type === 'missing_fields') {
    missingFieldsByDoc[error.document] = error.fields;
  }
});

if (Object.keys(missingFieldsByDoc).length > 0) {
  feedbackMessage += `\n**REQUIRED FIELDS CHECKLIST:**\n`;
  Object.entries(missingFieldsByDoc).forEach(([docType, fields]) => {
    feedbackMessage += `\n${docType.toUpperCase()}:\n`;
    fields.forEach(field => {
      feedbackMessage += `  ☐ ${field.replace(/_/g, ' ')}\n`;
    });
  });
}

feedbackMessage += `\n\nPlease review and resubmit your documents with the corrections.\n\n`;
feedbackMessage += `If you have questions, reply to this email.\n\n`;
feedbackMessage += `Best regards,\nSupplier Onboarding Team`;

return {
  json: {
    feedback_message: feedbackMessage,
    error_count: validation.errors.length,
    warning_count: validation.warnings.length,
    validation_details: validation
  }
};

const documents = $json.documents;
const validation = $json.validation;

// Create supplier record
const supplierRecord = {
  supplier_id: `SUP-${Date.now()}`,
  supplier_name: $json.supplier_name,
  supplier_email: $json.supplier_email,
  status: 'validated',
  submission_date: $json.submission_date,
  validated_date: new Date().toISOString(),

  // Aggregate data from all documents
  company_info: {
    legal_name: documents[0].extracted_data.company_name,
    tax_id: documents.find(d => d.document_type === 'tax_form')?.extracted_data.tax_id,
    address: documents.find(d => d.document_type === 'tax_form')?.extracted_data.address,
    contact_email: documents[0].extracted_data.email,
    contact_phone: documents[0].extracted_data.phone
  },

  // Insurance info
  insurance: {
    coverage_amount: documents.find(d => d.document_type === 'insurance')?.extracted_data.coverage_amount,
    expiration_date: documents.find(d => d.document_type === 'insurance')?.extracted_data.expiration_date,
    policy_number: documents.find(d => d.document_type === 'insurance')?.extracted_data.certificate_number
  },

  // Certifications
  certifications: documents
    .filter(d => d.document_type === 'certification')
    .map(d => ({
      type: d.extracted_data.issuing_authority,
      number: d.extracted_data.certificate_number,
      expiration: d.extracted_data.expiration_date
    })),

  // All extracted documents
  documents: documents,

  // Validation summary
  validation_score: 100, // Passed all checks
  warnings: validation.warnings
};

return { json: supplierRecord };

// Get all documents and their binary data from Aggregate node
const documents = $node["Aggregate All Processed Documents"].json.item;
const binaryData = $node["Aggregate All Processed Documents"].binary;

// Get all binary keys (like 'item0', 'item1', etc.)
const binaryKeys = Object.keys(binaryData || {});

// Create an array of items, each with its JSON data and corresponding binary
const items = documents.map((doc, index) => {
  const binaryKey = binaryKeys[index];

  return {
    json: {
      filename: doc.original_filename,
      document_type: doc.document_type
    },
    binary: {
      data: binaryData[binaryKey] // Assign the correct binary data
    }
  };
});

// Return all items at once
return items;
